<?php
require_once __DIR__.'/../../includes/staff/auth.php';require_permission('design.assign');verify_csrf();$pdo=staff_db();$main=customer_db();$me=current_staff();
if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare("INSERT INTO design_assignments(design_id,design_code,assigned_to,assigned_by,assignment_type,status,notes) VALUES(?,?,?,?,?,'assigned',?)");$s->execute([$_POST['design_id']?:null,trim($_POST['design_code']),$_POST['assigned_to'],$me['id'],$_POST['assignment_type'],trim($_POST['notes'])?:null]);staff_redirect('staff/admin/design-assignments.php');}
$staff=$pdo->query("SELECT id,staff_code,first_name,last_name FROM staff WHERE is_active=1 ORDER BY first_name")->fetchAll();$designs=$main?$main->query("SELECT id,design_code,design_name FROM designs ORDER BY created_at DESC")->fetchAll():[];$rows=$pdo->query("SELECT da.*,CONCAT(s.first_name,' ',COALESCE(s.last_name,'')) staff_name FROM design_assignments da JOIN staff s ON s.id=da.assigned_to ORDER BY da.assigned_at DESC")->fetchAll();$pageTitle='Design Assignments';require __DIR__.'/../../includes/staff/header.php';?>
<main class="staff-content"><div class="page-head"><div><p class="eyebrow">Workflow</p><h1>Design assignments</h1></div></div><div class="split-grid"><section class="staff-panel"><h2>Assign design</h2><form method="post"><?= csrf_field() ?><?php if($designs):?><label>Saved design<select id="designSelect" onchange="syncDesign()"><option value="">Choose…</option><?php foreach($designs as $d):?><option value="<?= $d['id'] ?>" data-code="<?= h($d['design_code']) ?>"><?= h($d['design_code'].' — '.($d['design_name']?:'Untitled')) ?></option><?php endforeach;?></select></label><?php endif;?><input type="hidden" name="design_id" id="designId"><label>Design code<input name="design_code" id="designCode" required></label><label>Assign to<select name="assigned_to"><?php foreach($staff as $s):?><option value="<?= $s['id'] ?>"><?= h(trim($s['first_name'].' '.$s['last_name'])) ?></option><?php endforeach;?></select></label><label>Type<select name="assignment_type"><option>consultation</option><option selected>design</option><option>quotation</option><option>review</option><option>installation</option><option>follow_up</option></select></label><label>Notes<textarea name="notes"></textarea></label><button class="btn primary">Assign design</button></form></section><section class="staff-panel table-panel"><table><thead><tr><th>Design</th><th>Staff</th><th>Type</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= h($r['design_code']) ?></td><td><?= h($r['staff_name']) ?></td><td><?= h($r['assignment_type']) ?></td><td><?= h($r['status']) ?></td></tr><?php endforeach;?></tbody></table></section></div></main><script>function syncDesign(){let s=document.getElementById('designSelect'),o=s.options[s.selectedIndex];document.getElementById('designId').value=o.value;document.getElementById('designCode').value=o.dataset.code||'';}</script><?php require __DIR__.'/../../includes/staff/footer.php';?>
